// common-generation.ts
/**
 * Common map script used by map generators and world builder to add various features to the map.
 * @packageDocumentation
 */

import { addHills, buildRainfallMap } from "#base/maps/elevation-terrain-generator.js";
import { addFeatures, designateBiomes } from "#base/maps/feature-biome-generator.js";
import {
	dumpBiomes,
	dumpContinents,
	dumpElevation,
	dumpFeatures,
	dumpRainfall,
	dumpResources,
	dumpTerrain,
} from "#base/maps/map-debug-helpers.js";
import * as globals from "#base/maps/map-globals.js";
import { addNaturalWonders } from "#base/maps/natural-wonder-generator.js";
import { generateResources } from "#base/maps/resource-generator.js";
import { dumpPermanentSnow, generateSnow } from "#base/maps/snow-generator.js";
import { HexMap } from "#base/scripts/hex-map.js";
import { profileFunction, profileScope } from "#base/scripts/profiling.js";

export enum GenerationPhases {
	Lakes = 1 << 0,
	Elevation = 1 << 1,
	Hills = 1 << 2,
	Rainfall = 1 << 3,
	Rivers = 1 << 4,
	Biomes = 1 << 5,
	NaturalWonders = 1 << 6,
	FloodPlains = 1 << 7,
	Features = 1 << 8,
	Snow = 1 << 9,
	Resources = 1 << 10,

	All = (1 << 11) - 1,
}

export async function generateMapFeatures(hexMap: HexMap, phases: GenerationPhases = GenerationPhases.All) {
	// TODO:
	// - Check validateAndFixTerrain() to see if it's actually needed after each step
	// - Move these functions out to their own file that can be shared, and pass in which
	//   phases to do as parameters so it can be shared between maps and used by world builder.

	const generateMapFeaturesScope: profileScope = new profileScope("Generate Features");
	const iWidth = GameplayMap.getGridWidth();
	const iHeight = GameplayMap.getGridHeight();
	const uiMapSize = GameplayMap.getMapSize();

	const mapInfo = GameInfo.Maps.lookup(uiMapSize);
	if (mapInfo == null) return;

	const iNumNaturalWonders: number = mapInfo.NumNaturalWonders;

	// Generate lakes and update lake tiles with water tags.
	if (phases & GenerationPhases.Lakes) {
		profileFunction("generateLakes", () => hexMap.GenerateLakes());
		hexMap.writeToTerrainBuilder();
	}

	profileFunction("TerrainBuilder.validateAndFixTerrain", () => TerrainBuilder.validateAndFixTerrain());
	profileFunction("AreaBuilder.recalculateAreas", () => AreaBuilder.recalculateAreas());
	profileFunction("TerrainBuilder.stampContinents", () => TerrainBuilder.stampContinents());

	profileFunction("AreaBuilder.recalculateAreas", () => AreaBuilder.recalculateAreas());
	profileFunction("TerrainBuilder.buildElevation", () => TerrainBuilder.buildElevation());
	profileFunction("addHills", () => addHills(iWidth, iHeight));
	profileFunction("buildRainfallMap", () => buildRainfallMap(iWidth, iHeight));
	profileFunction("TerrainBuilder.modelRivers", () =>
		TerrainBuilder.modelRivers(5, 15, globals.g_NavigableRiverTerrain),
	);
	profileFunction("TerrainBuilder.validateAndFixTerrain", () => TerrainBuilder.validateAndFixTerrain());
	profileFunction("TerrainBuilder.defineNamedRivers", () => TerrainBuilder.defineNamedRivers());
	profileFunction("designateBiomes", () => designateBiomes(iWidth, iHeight));
	profileFunction("addNaturalWonders", () => addNaturalWonders(iWidth, iHeight, iNumNaturalWonders));
	profileFunction("TerrainBuilder.addFloodplains", () => TerrainBuilder.addFloodplains(4, 10));
	profileFunction("addFeatures", () => addFeatures(iWidth, iHeight));
	profileFunction("TerrainBuilder.validateAndFixTerrain", () => TerrainBuilder.validateAndFixTerrain());
	profileFunction("AreaBuilder.recalculateAreas", () => AreaBuilder.recalculateAreas());
	profileFunction("TerrainBuilder.storeWaterData", () => TerrainBuilder.storeWaterData());
	profileFunction("generateSnow", () => generateSnow(iWidth, iHeight));

	dumpContinents(iWidth, iHeight);
	dumpTerrain(iWidth, iHeight);
	dumpElevation(iWidth, iHeight);
	dumpRainfall(iWidth, iHeight);
	dumpBiomes(iWidth, iHeight);
	dumpFeatures(iWidth, iHeight);
	dumpPermanentSnow(iWidth, iHeight);

	profileFunction("generateResources", () => generateResources(iWidth, iHeight));
	dumpResources(iWidth, iHeight);
	generateMapFeaturesScope.end();
}
